static inline const case_kind* kind_of(cx_u32 cp) {
    if (__builtin_expect(cp < 0x40000, 1)) return &kinds[stage2[(cx_u32)stage1[cp >> 7] << 7 | (cp & 127)]];
    if (cp >= 0xE0020 && cp <= 0xE007E) return &kinds[118];
    if (cp >= 0xE0100 && cp <= 0xE01EF) return &kinds[87];
    return &kinds[0];
}
/* --- end of the generated tables --- */

/* The code point `c` as UTF-8 at `o`, which has room for 4 bytes. Returns how many it took. */
static inline cx_usize put_utf8(cx_u8* o, cx_u32 c) {
    if (c < 0x80) {
        o[0] = (cx_u8)c;
        return 1;
    }
    if (c < 0x800) {
        o[0] = (cx_u8)(0xC0 | (c >> 6));
        o[1] = (cx_u8)(0x80 | (c & 0x3F));
        return 2;
    }
    if (c < 0x10000) {
        o[0] = (cx_u8)(0xE0 | (c >> 12));
        o[1] = (cx_u8)(0x80 | ((c >> 6) & 0x3F));
        o[2] = (cx_u8)(0x80 | (c & 0x3F));
        return 3;
    }
    o[0] = (cx_u8)(0xF0 | (c >> 18));
    o[1] = (cx_u8)(0x80 | ((c >> 12) & 0x3F));
    o[2] = (cx_u8)(0x80 | ((c >> 6) & 0x3F));
    o[3] = (cx_u8)(0x80 | (c & 0x3F));
    return 4;
}

/* Where the ASCII from `i` ends: eight bytes at a time, then one. */
static inline cx_usize ascii_end(const cx_u8* p, cx_usize i, cx_usize n) {
    while (n - i >= 8) {
        cx_u64 w;
        memcpy(&w, p + i, 8);
        if (w & 0x8080808080808080ull) break;
        i += 8;
    }
    while (i < n && p[i] < 0x80) i++;
    return i;
}

/* Room for `more` bytes after what `r` holds. */
static inline void room(cx_String* r, cx_usize more) {
    if (r->cap - r->len < more) cx_string_reserve(r, more);
}

/* --- words, for the final sigma -------------------------------------------------------------- */

static inline cx_usize skip_marks(const cx_u8* w, cx_usize j, cx_usize n) {
    while (j < n && (w[j] == W_X || w[j] == W_XF)) j++;
    return j;
}

/* The class after any format characters from `j`, or -1 at the end. */
static inline int after_format(const cx_u8* w, cx_usize j, cx_usize n) {
    while (j < n && w[j] == W_XF) j++;
    return j < n ? w[j] : -1;
}

/* Where the word starting at code point `i` ends, with `w` the code points' classes. A word is
 * letters and digits, with a period, an apostrophe, a hyphen or the like between two letters,
 * a comma, a period or the like between two digits, and a percent sign or the like after the
 * digits, ending it. Marks and format characters go with what's before them, and format
 * characters don't keep punctuation from being between two letters. Whitespace, kanji, hiragana
 * and katakana each make a word of a run, and anything else is a word by itself. */
static cx_usize word_end(const cx_u8* w, cx_usize i, cx_usize n) {
    int c = w[i];
    cx_usize j = i + 1;
    switch (c) {
        case W_L:
        case W_D: {
            j = skip_marks(w, j, n);
            int prev = c;
            while (j < n) {
                int k = w[j];
                if (k == W_L || k == W_D) {
                    if (prev == W_DANDA && k == W_L) break;  // after a danda, only digits go on
                    prev = k;
                    j = skip_marks(w, j + 1, n);
                } else if ((k == W_MW || k == W_MWN) && prev == W_L && after_format(w, j + 1, n) == W_L) {
                    j = skip_marks(w, j + 1, n);
                } else if ((k == W_MN || k == W_MWN) && prev == W_D && after_format(w, j + 1, n) == W_D) {
                    j = skip_marks(w, j + 1, n);
                } else if (k == W_POST && prev == W_D) {
                    return j + 1;
                } else if (k == W_DANDA && prev == W_L) {
                    j++;
                    while (j < n && w[j] == W_XF) j++;
                    prev = W_DANDA;
                } else {
                    break;
                }
            }
            return j;
        }
        case W_WS:
            while (j < n && (w[j] == W_WS || w[j] == W_X || w[j] == W_XF)) j++;
            if (j < n && w[j] == W_CR) j++;
            if (j < n && w[j] == W_LS) j++;
            return skip_marks(w, j, n);
        case W_CR:
            if (j < n && w[j] == W_LS) j++;
            return skip_marks(w, j, n);
        case W_K:
        case W_H:
        case W_KA:
            while (j < n && (w[j] == c || w[j] == W_X || w[j] == W_XF)) j++;
            return j;
        case W_X:
        case W_XF:
            return j;
        default:
            return skip_marks(w, j, n);
    }
}

/* For each capital sigma in `s`, in order, whether its lowercase is the final form: whether its
 * word has a cased code point before it and none after. Java also ends a word after any code
 * point past U+FFFF but the text's first, without ending the run of letters it's in. */
static void sigma_finals(cx_str s, cx_u8* finals) {
    cx_usize n = 0;
    for (cx_usize i = 0; i < s.len; i++) n += (s.ptr[i] & 0xC0) != 0x80;
    cx_usize bytes = n * (sizeof(cx_u32) + 2);
    cx_u8* mem = (cx_u8*)cx_alloc(bytes);
    cx_u32* cps = (cx_u32*)mem;
    cx_u8* w = mem + n * sizeof(cx_u32);
    cx_u8* cased = w + n;
    for (cx_usize i = 0, k = 0; i < s.len; k++) {
        cps[k] = cx_utf8_next(s.ptr, &i);
        const case_kind* kind = kind_of(cps[k]);
        w[k] = kind->word;
        cased[k] = kind->flags & CASED;
    }
    cx_usize at = 0;  // the next sigma's place in `finals`
    for (cx_usize start = 0; start < n;) {
        cx_usize end = word_end(w, start, n);
        cx_usize from = start;
        for (cx_usize q = start; q < end; q++) {
            if (q + 1 < end && !(q > 0 && cps[q] >= 0x10000)) continue;
            /* The word from `from` to `q`, inclusive. */
            for (cx_usize i = from; i <= q; i++) {
                if (cps[i] != 0x3A3) continue;
                cx_bool before = 0, after = 0;
                for (cx_usize b = from; b < i; b++) before |= cased[b];
                for (cx_usize a = i + 1; a <= q; a++) after |= cased[a];
                finals[at++] = before && !after;
            }
            from = q + 1;
        }
        start = end;
    }
    cx_free(mem, bytes);
}

/* --- lowercase and uppercase --------------------------------------------------------------- */

/* Whether code point `c` changes. */
static inline cx_bool lower_changes(cx_u32 c) {
    const case_kind* k = kind_of(c);
    return k->lower != 0 || (k->flags & LOW_MANY);
}
static inline cx_bool upper_changes(cx_u32 c) {
    const case_kind* k = kind_of(c);
    return k->upper != 0 || (k->flags & UP_MANY);
}

/* Where the first byte that changes is, or `n`: the text before it is copied as it is. */
static cx_usize first_change(const cx_u8* p, cx_usize n, cx_bool lower) {
    cx_u8 from = lower ? 'A' : 'a';
    for (cx_usize i = 0; i < n;) {
        if (p[i] < 0x80) {
            if ((cx_u8)(p[i] - from) < 26) return i;
            i++;
            continue;
        }
        cx_usize at = i;
        cx_u32 c = cx_utf8_next(p, &i);
        if (lower ? lower_changes(c) : upper_changes(c)) return at;
    }
    return n;
}

/* A copy of the text with nothing changed. Text that's a literal, `keep`, isn't copied. */
static cx_String unchanged(cx_str s, cx_bool keep) {
    if (keep || s.len == 0) return (cx_String){(cx_u8*)s.ptr, s.len, 0};
    cx_String r = {0, 0, 0};
    cx_string_push_bytes(&r, s.ptr, s.len);
    return r;
}

cx_String cx_case_lower(cx_str s, cx_bool keep) {
    const cx_u8* p = s.ptr;
    cx_usize n = s.len;
    cx_usize i = first_change(p, n, 1);
    if (i == n) return unchanged(s, keep);
    cx_String r = {0, 0, 0};
    room(&r, n + 8);
    memcpy(r.ptr, p, i);
    r.len = i;
    /* Which capital sigmas are final, worked out at the first. */
    cx_u8 small[16];
    cx_u8* finals = 0;
    cx_usize sigmas = 0, at = 0;
    while (i < n) {
        cx_usize j = ascii_end(p, i, n);
        if (j > i) {
            room(&r, j - i);
            cx_u8* o = r.ptr + r.len;
            for (cx_usize k = i; k < j; k++) {
                cx_u8 c = p[k];
                o[k - i] = (cx_u8)(c + ((cx_u8)(c - 'A') < 26 ? 32 : 0));
            }
            r.len += j - i;
            i = j;
            if (i == n) break;
        }
        cx_u32 c = cx_utf8_next(p, &i);
        const case_kind* k = kind_of(c);
        room(&r, 8);
        if (k->flags & SIGMA) {
            if (!finals) {
                for (cx_usize b = 0; b + 1 < n; b++) sigmas += p[b] == 0xCE && p[b + 1] == 0xA3;
                finals = sigmas <= sizeof small ? small : (cx_u8*)cx_alloc(sigmas);
                sigma_finals(s, finals);
            }
            c = finals[at++] ? 0x3C2 : 0x3C3;
        } else if (k->flags & LOW_MANY) {
            r.ptr[r.len++] = 'i';  // U+0130: an i, then a combining dot above
            c = 0x307;
        } else {
            c = (cx_u32)((cx_i32)c + k->lower);
        }
        r.len += put_utf8(r.ptr + r.len, c);
    }
    if (finals && finals != small) cx_free(finals, sigmas);
    return r;
}

/* The uppercase of `c`, when it's more than one code point. */
static const cx_u32* upper_many(cx_u32 c) {
    cx_usize lo = 0, hi = sizeof up_many / sizeof up_many[0];
    while (lo < hi) {
        cx_usize mid = (lo + hi) / 2;
        if (up_many[mid].cp < c) lo = mid + 1;
        else hi = mid;
    }
    return up_many[lo].to;
}

cx_String cx_case_upper(cx_str s, cx_bool keep) {
    const cx_u8* p = s.ptr;
    cx_usize n = s.len;
    cx_usize i = first_change(p, n, 0);
    if (i == n) return unchanged(s, keep);
    cx_String r = {0, 0, 0};
    room(&r, n + 8);
    memcpy(r.ptr, p, i);
    r.len = i;
    while (i < n) {
        cx_usize j = ascii_end(p, i, n);
        if (j > i) {
            room(&r, j - i);
            cx_u8* o = r.ptr + r.len;
            for (cx_usize k = i; k < j; k++) {
                cx_u8 c = p[k];
                o[k - i] = (cx_u8)(c - ((cx_u8)(c - 'a') < 26 ? 32 : 0));
            }
            r.len += j - i;
            i = j;
            if (i == n) break;
        }
        cx_u32 c = cx_utf8_next(p, &i);
        const case_kind* k = kind_of(c);
        room(&r, 12);
        if (k->flags & UP_MANY) {
            const cx_u32* to = upper_many(c);
            for (int m = 0; m < 3 && to[m]; m++) r.len += put_utf8(r.ptr + r.len, to[m]);
        } else {
            r.len += put_utf8(r.ptr + r.len, (cx_u32)((cx_i32)c + k->upper));
        }
    }
    return r;
}
